const fresh=(key,ttl=15000)=>Date.now()-(dataLoaded[key]||0)<ttl;
const invalidate=(...keys)=>keys.forEach(k=>dataLoaded[k]=0);
async function workData(force=false){if(!S.own)return false;if(!force&&fresh('work'))return false;const before=JSON.stringify([S.bookings,S.blocks]);const id=S.own.id;[S.bookings,S.blocks]=await Promise.all([api('/bookings?scope=company&company='+id),api('/v2/blocks?company='+id)]);dataLoaded.work=Date.now();return before!==JSON.stringify([S.bookings,S.blocks])}
async function loadPageData(page,force=false){let changed=false;if(!isClient()&&['dashboard','calendar','clients','analytics'].includes(page)){changed=await workData(force)||changed;if(page==='clients'&&(force||!fresh('clients'))){const before=JSON.stringify(S.clients);S.clients=await api('/v2/clients?company='+S.own.id);dataLoaded.clients=Date.now();changed=changed||before!==JSON.stringify(S.clients)}}if(!isClient()&&page==='reviews'&&(force||!fresh('reviews'))){const before=JSON.stringify(S.reviews);S.reviews=(await api('/v7/reviews?company='+S.own.id+'&limit=100')).items;dataLoaded.reviews=Date.now();changed=before!==JSON.stringify(S.reviews)||changed}if(isClient()&&page==='my'&&S.me&&(force||!fresh('my'))){const before=JSON.stringify(S.bookings);S.bookings=await api('/bookings');dataLoaded.my=Date.now();changed=before!==JSON.stringify(S.bookings)||changed}if(page==='admin'&&(force||!fresh('admin'))){const before=JSON.stringify(S.admin||null);S.admin=await api('/v5/admin');dataLoaded.admin=Date.now();changed=before!==JSON.stringify(S.admin)||changed}if(!isClient()&&page==='subscription'&&(force||!fresh('subscription'))){const before=JSON.stringify(S.subscriptionStats||null);S.subscriptionStats=await api('/v8/subscription-stats?company='+S.own.id);dataLoaded.subscription=Date.now();changed=before!==JSON.stringify(S.subscriptionStats)||changed}return changed}
function pageCached(page){if(!isClient()&&['dashboard','calendar','analytics'].includes(page))return !!dataLoaded.work;if(!isClient()&&page==='clients')return !!dataLoaded.work&&!!dataLoaded.clients;if(!isClient()&&page==='reviews')return !!dataLoaded.reviews;if(isClient()&&page==='my')return !S.me||!!dataLoaded.my;if(page==='admin')return !!dataLoaded.admin;if(!isClient()&&page==='subscription')return !!dataLoaded.subscription;return true}
function paintPage(view,page,version){if(version!==renderVersion||page!==S.page)return;const pages={admin:adminPage,landing,register:registration,dashboard,calendar:calendarPage,clients:clientsPage,more,services:servicesPage,share:sharePage,settings:settingsPage,reviews:reviewsPage,subscription:subscriptionPage,analytics:analyticsPage,client:clientPage,my:myBookings,profile,help:helpPage,legal:legalPage};view.innerHTML=(pages[page]||landing)();localizeDOM(view,S.language);if(page==='admin')initAdmin(view,api,S.language);if(S.config?.flags?.reviews===false)view.querySelectorAll('[data-page=reviews]').forEach(e=>e.remove());if(S.config?.flags?.help===false)view.querySelectorAll('[data-page=help]').forEach(e=>e.remove());view.classList.remove('screen-enter');void view.offsetWidth;view.classList.add('screen-enter');syncShell();if(page==='landing')requestAnimationFrame(()=>initLandingMotion());if(page==='settings')loadDeliveryStatus();if(page==='client'&&S.me&&!S.preview)loadClientNext()}
async function render({force=false}={}){const version=++renderVersion;if(S.page==='admin'&&!S.me?.owner)S.page='landing';if(isClient()&&!['client','my','profile','help','legal','admin'].includes(S.page))S.page='client';if(!isClient()&&!S.own&&!['landing','register','admin'].includes(S.page))S.page='landing';shell();const page=S.page,view=document.querySelector('#view');if(S.tour&&page!=='admin'){view.innerHTML=tour();return}const cached=pageCached(page)&&!force;if(cached){paintPage(view,page,version);loadPageData(page,false).then(changed=>{if(changed&&version===renderVersion&&page===S.page){const y=scrollY;paintPage(view,page,version);requestAnimationFrame(()=>scrollTo({top:y,behavior:'auto'}))}}).catch(()=>{});return}view.innerHTML=skeleton();try{await loadPageData(page,true);paintPage(view,page,version)}catch(e){if(version===renderVersion)view.innerHTML=empty('Не удалось загрузить',translateText(e.message,S.language),'<button class="primary" id="refresh">Повторить</button>')}}
function tour(){if(!isClient())return landing();const x=S.tenant;return `<section class="client-intro">${imageTag(x?.photo,x?.name)}<span class="eyebrow">ВАША ЛИЧНАЯ СТРАНИЦА ЗАПИСИ</span><h1>Запись к ${esc(x?.name||'специалисту')}</h1><p>Выберите услугу и удобное время — всё займёт меньше минуты.</p><button class="primary" id="skip-tour">Записаться ${icon('arrow')}</button><ol class="v3-steps">${['Выберите услугу','Найдите удобное время','Подтвердите запись','За 24 часа подтвердите визит, за 2 часа Takt напомнит 🔔'].map((t,i)=>`<li><span>0${i+1}</span><p>${t}</p></li>`).join('')}</ol><p class="note">Ваши будущие встречи и история — в разделе «Мои записи».</p></section>`}
async function openLinkedBooking(){const p=new URLSearchParams(location.search),id=p.get('booking');if(!id||!S.bookings.some(b=>b.id===id))return;const action=p.get('action');if(action==='review'){reviewEditor(id);return}visitActions(id);if(action==='client'&&S.own){S.clients=await api('/v2/clients?company='+S.own.id);const b=S.bookings.find(x=>x.id===id);clientDetails(b.user_id)}if(action==='move')sheet.querySelector('[data-move]')?.click();if(action==='cancel')sheet.querySelector('[data-cancel]')?.click();history.replaceState(null,'',location.pathname+(S.tenant?'?company='+encodeURIComponent(S.tenant.id):''))}
async function finishTour(){if(S.me)try{await post('/v2/preferences',{mode:S.mode})}catch{toast('Знакомство сохранено на этом устройстве')}stored('tour-'+S.mode,'2');S.tour=false;if(isClient()&&new URLSearchParams(location.search).has('booking'))S.page='my';await render();openLinkedBooking().catch(e=>toast(e.message));scrollTo({top:0})}
function login(){return empty('Откройте в Telegram','Для записи и личного кабинета нужен ваш Telegram-аккаунт.',`<a class="primary" href="https://t.me/takt_service_bot?startapp=${isClient()&&S.tenant?(S.tenant.username?'u_'+S.tenant.username:'c_'+S.tenant.id):'register'}">Открыть приложение</a>`)}
function photoField(key,current=''){return `<label class="photo-picker">${imageTag(current,'Фото','upload-avatar')}<span>Добавить фото<small>JPG, PNG · сожмём автоматически</small></span><input type="file" accept="image/jpeg,image/png,image/webp" data-photo="${key}" aria-label="Загрузить фото"></label>`}
function intervalInputs(i,d){return `<div class="work-interval"><label><small>Начало</small><input type="time" name="start${i}" value="${minute(d.start)}" step="300" aria-label="Начало работы"></label><span class="interval-arrow">→</span><label><small>Окончание</small><input type="time" name="end${i}" value="${minute(d.end===1440?0:d.end)}" step="300" aria-label="Окончание работы"></label><button type="button" class="interval-remove" data-remove-interval aria-label="Удалить интервал">×</button></div>`}
function scheduleFields(hours){return `<p class="schedule-help">Для каждого дня укажите время работы. Добавьте второй интервал, если нужен перерыв в течение дня.</p><div class="schedule-editor">${[1,2,3,4,5,6,0].map(i=>{const d=hours[i],parts=d?(Array.isArray(d)?d:[d]):[{start:540,end:1080}];return `<div class="work-day"><label class="day-check"><input type="checkbox" name="day${i}" ${d?'checked':''}><span>${['Воскресенье','Понедельник','Вторник','Среда','Четверг','Пятница','Суббота'][i]}</span></label><div class="work-intervals" data-day-intervals="${i}">${parts.map(d=>intervalInputs(i,d)).join('')}</div><button type="button" class="text-button" data-add-interval="${i}">＋ Интервал после перерыва</button><button type="button" class="text-button" data-copy-day="${i}">Применить к другим дням</button></div>`}).join('')}</div><p class="note">Промежутки между интервалами — перерывы. Выключите день, чтобы сделать его выходным. Конец в 00:00 означает полночь.</p>`}
function readSchedule(f){return Array.from({length:7},(_,i)=>f.get('day'+i)?f.getAll('start'+i).map((v,k)=>({start:parseTime(v),end:parseTime(f.getAll('end'+i)[k])||1440})):null)}
function registration(){if(!S.me)return login();if(S.own)return empty('Ваша страница уже готова','Все услуги находятся в вашем личном кабинете.',button('Перейти в кабинет','dashboard'));const b=S.draft;return `${heading('Создадим вашу страницу','Короткая настройка — и можно приглашать клиентов.')}<div class="setup-progress">${['О вас','Первая услуга','Расписание'].map((t,i)=>`<span class="${S.step===i?'active':''}">${i+1}. ${t}</span>`).join('')}</div><section class="editor-card"><form id="register-form"><span class="eyebrow">Шаг ${S.step+1} из 3</span><h2>${['Давайте познакомимся','С чего начнём запись?','Когда вы принимаете?'][S.step]}</h2>${S.step===0?`${photoField('draft',b.photo)}<label>Имя или название<input name="name" value="${esc(b.name)}" minlength="2" maxlength="80" required placeholder="Например, Давуд · барбер"></label><label>Чем вы занимаетесь<select name="category">${Object.entries(cats).map(([v,t])=>`<option value="${v}" ${b.category===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Коротко о вас<textarea name="tagline" maxlength="160" placeholder="Ваш подход, опыт или специализация">${esc(b.tagline)}</textarea></label><label>Адрес или формат работы<input name="address" value="${esc(b.address)}" maxlength="200" placeholder="Адрес, выезд или онлайн"></label><label>Телефон · по желанию<input type="tel" name="phone" value="${esc(b.phone)}" maxlength="24"></label>`:S.step===1?`<label>Название услуги<input name="service_name" value="${esc(b.service_name)}" minlength="2" maxlength="120" required placeholder="Например, стрижка + борода"></label><div class="form-grid"><label>Стоимость, ₽<input type="number" name="price" min="0" max="1000000" value="${b.price}" required></label><label>Длительность, мин<input type="number" name="duration" min="15" max="480" step="5" value="${b.duration}" required></label></div><label>Что входит<textarea name="description" maxlength="700">${esc(b.description)}</textarea></label>`:scheduleFields(b.schedule)}<div class="form-error" role="alert"></div><div class="actions">${S.step?'<button type="button" class="secondary" id="register-back">Назад</button>':''}<button class="primary" type="submit">${S.step===2?'Создать страницу':'Продолжить'} ${icon('arrow')}</button></div></form></section>`}
function saveDraft(){const form=document.querySelector('#register-form');if(!form)return;const f=new FormData(form);if(S.step===2)S.draft.schedule=readSchedule(f);else Object.assign(S.draft,Object.fromEntries(f))}
const active=b=>['pending','confirmed'].includes(b.status),future=b=>active(b)&&b.ends_at>Date.now()/1000;
const attendanceInfo=b=>{if(!active(b))return ['', '', ''];const state=b.attendance_state||'unknown',left=b.starts_at-Date.now()/1000;if(state==='coming')return ['coming','✅ Визит подтверждён клиентом',''];if(state==='not_coming')return ['not_coming','❌ Клиент сообщил, что не придёт',''];return left<=7200?['unknown','⚠️ Ответа клиента пока нет','До визита меньше 2 часов']:['unknown','🕘 Ожидаем подтверждение клиента','']};
const until=t=>{const sec=Math.max(0,t-Date.now()/1000),m=Math.round(sec/60);if(m<60)return `через ${m} мин`;const h=Math.floor(m/60),r=m%60;if(h<24)return `через ${h} ч${r?' '+r+' мин':''}`;const d=Math.floor(h/24);return `через ${d} дн`};
const trialText=x=>!x?.subscription?'':x.subscription.status==='trial'?`Пробный период · ${x.subscription.days_left} дн.`:x.subscription.status==='active'?'Подписка активна':'Пробный период закончился';
function bookingCard(b,admin=false){const att=admin&&active(b)?attendanceInfo(b):null;return `<article class="visit-card" data-booking-card="${b.id}"><div class="visit-time"><strong>${time(b.starts_at)}</strong><span>${dateLabel(date(b.starts_at))}</span></div><div class="visit-info"><h3>${esc(b.service_name)}</h3><p>${esc(admin?b.name:b.company_name||S.tenant?.name||'Специалист')}</p><span class="badge ${b.status}">${labels[b.visit_outcome||b.status]||labels[b.status]}</span>${att?`<span class="attendance visit-confirmation ${att[0]}">${att[1]}</span>`:''}</div><div class="visit-end"><strong>${money(b.price)}</strong><button class="more-button" data-visit="${b.id}" aria-label="Действия с записью">•••</button></div></article>`}
function dashboard(){const now=Date.now()/1000,today=S.bookings.filter(b=>date(b.starts_at)===day()),futureRows=S.bookings.filter(future).sort((a,b)=>a.starts_at-b.starts_at),upcoming=futureRows.slice(0,3),earned=today.filter(b=>b.status!=='cancelled'&&b.visit_outcome!=='no_show').reduce((a,b)=>a+b.price,0);const attention=futureRows.filter(b=>b.status==='pending'||b.attendance_state==='not_coming'||(b.attendance_state!=='coming'&&b.starts_at-now<=7200));const reason=b=>b.attendance_state==='not_coming'?['danger','Клиент сообщил, что не придёт']:b.status==='pending'?['warn','Новая запись — подтвердите её']:['muted','Ответа клиента пока нет · до визита меньше 2 часов'];const contactButtons=b=>`${/^[0-9]+$/.test(String(b.user_id))?`<button class="text-button compact" data-message-client="${esc(b.user_id)}">Написать</button>`:''}${b.phone?`<button class="text-button compact" data-call="${esc(b.phone)}">Позвонить</button>`:''}`;const attentionBlock=attention.length?`<section class="attention-panel"><div class="attention-head"><div><span class="eyebrow">ВАЖНО СЕЙЧАС</span><h2>Требуют внимания</h2></div><strong>${attention.length}</strong></div><div class="attention-list">${attention.slice(0,4).map(b=>{const q=reason(b);return `<article class="attention-row"><div class="attention-main"><strong>${time(b.starts_at)} · ${esc(b.name)}</strong><span>${dateLabel(date(b.starts_at))} · ${esc(b.service_name)}</span><small class="attention-reason ${q[0]}">${q[1]}</small></div><div class="attention-actions">${b.status==='pending'?`<button class="primary compact" data-status="confirmed" data-id="${b.id}">Подтвердить</button>`:''}<button class="secondary compact" data-visit="${b.id}">Открыть</button>${contactButtons(b)}</div></article>`}).join('')}</div></section>`:'';const nextBlock=upcoming.length?`<section class="next72"><div class="next72-head"><div><span class="eyebrow">БЛИЖАЙШИЕ ЗАПИСИ</span><h2>Ближайшие записи</h2></div><button class="next72-calendar" data-page="calendar">Расписание →</button></div><div class="next72-list">${upcoming.map((b,i)=>{const att=attendanceInfo(b),duration=Math.round((b.ends_at-b.starts_at)/60),state=b.status==='pending'?'Новая запись':att[1];return `<article class="next72-row ${i===0?'primary-row':''}"><div class="next72-time"><strong>${time(b.starts_at)}</strong><span>${dateLabel(date(b.starts_at))}</span>${i===0?`<small>${until(b.starts_at)}</small>`:''}</div><div class="next72-client"><h3>${esc(b.name)}</h3><p>${esc(b.service_name)}</p><small>${duration} мин · ${money(b.price)}</small></div><div class="next72-state"><span>${esc(state)}</span>${att[2]?`<small>${esc(att[2])}</small>`:''}</div><div class="next72-actions"><button class="next72-open" data-visit="${b.id}">Открыть</button>${/^[0-9]+$/.test(String(b.user_id))?`<button class="next72-message" data-message-client="${esc(b.user_id)}">Написать</button>`:''}${b.phone?`<button class="next72-open" data-call="${esc(b.phone)}">Позвонить</button>`:''}</div></article>`}).join('')}</div></section>`:`<section class="next72 empty"><div><span class="eyebrow">БЛИЖАЙШИЕ ЗАПИСИ</span><h2>Пока всё свободно</h2><p>Добавьте клиента вручную или поделитесь своей ссылкой.</p></div><div class="next72-empty-actions"><button class="next72-message" data-manual>＋ Добавить запись</button><button class="next72-open" data-page="share">Моя ссылка</button></div></section>`;const rd=S.own.reviews||{average:0,count:0,items:[]},lastReview=rd.items?.[0],reviewBlock=rd.count?`<section class="dashboard-reviews"><button data-page="reviews"><span class="eyebrow">ОТЗЫВЫ</span><strong>${Number(rd.average||0).toFixed(1)} ★ · ${rd.count}</strong><small>${lastReview?.text?esc(lastReview.text):'Посмотреть все отзывы'}</small></button></section>`:'';return `${heading('Добрый день, '+S.own.name,'Сегодня · '+dateLabel(day()))}<section class="dashboard-kpis"><div><span>Записей сегодня</span><strong>${today.filter(active).length}</strong></div><div><span>Стоимость записей</span><strong>${money(earned)}</strong></div><div><span>Свободных окон</span><strong id="free-count">…</strong><small id="free-label"></small></div></section>${attentionBlock}<div class="section-heading quick-heading"><h2>Быстрые действия</h2></div><div class="quick-grid quick-grid-v8"><button data-manual>${icon('calendar')}Добавить запись</button><button data-edit-service="new">${icon('grid')}Добавить услугу</button><button data-page="share">${icon('link')}Моя ссылка</button><button id="block-time">${icon('clock')}Закрыть время</button></div>${nextBlock}${reviewBlock}<div class="section-heading"><h2>Записи на сегодня</h2><button data-page="calendar" class="text-button">Все →</button></div>${today.filter(b=>b.status!=='cancelled'&&b.visit_outcome!=='no_show').sort((a,b)=>a.starts_at-b.starts_at).map(b=>bookingCard(b,true)).join('')||'<div class="dashboard-empty"><h3>На сегодня всё свободно</h3><p>Можно поделиться ссылкой или добавить запись вручную.</p></div>'}`}
function calendarDaySheet(d){const rows=S.bookings.filter(b=>date(b.starts_at)===d&&b.status!=='cancelled').sort((a,b)=>a.starts_at-b.starts_at);openSheet(dateLabel(d),`<div class="calendar-day-sheet"><p class="dialog-sub">${new Date(d+'T12:00Z').toLocaleDateString(localeFor(S.language),{weekday:'long'})} · ${esc(zoneLabel(zone()))}</p>${rows.length?`<div class="calendar-day-list">${rows.map(b=>`<button data-visit="${b.id}"><span><strong>${time(b.starts_at)}–${time(b.ends_at)}</strong><small>${esc(b.service_name)} · ${esc(b.name)}</small></span><span>${money(b.price)}</span></button>`).join('')}</div>`:'<div class="calendar-day-empty"><strong>На этот день записей нет</strong><span>Можно сразу добавить клиента вручную.</span></div>'}<div class="calendar-day-actions"><button class="primary" data-manual-date="${d}">＋ Добавить клиента</button><button class="secondary" data-open-day="${d}">Открыть день</button></div></div>`)}
function calendarPage(){const n=S.calendar==='week'?7:S.calendar==='month'?new Date(Number(S.date.slice(0,4)),Number(S.date.slice(5,7)),0).getDate():1,start=S.calendar==='month'?S.date.slice(0,8)+'01':S.calendar==='week'?shift(S.date,-((new Date(S.date+'T12:00Z').getUTCDay()+6)%7)):S.date;const cards=Array.from({length:n},(_,i)=>{const d=shift(start,i),rows=S.bookings.filter(b=>date(b.starts_at)===d&&b.status!=='cancelled').sort((a,b)=>a.starts_at-b.starts_at),blocks=S.blocks.filter(b=>date(b.starts_at)<=d&&date(b.ends_at)>=d);return `<section class="calendar-day"><button class="calendar-date" data-date="${d}">${dateLabel(d)} <span>${new Date(d+'T12:00Z').toLocaleDateString(localeFor(S.language),{weekday:'short'})}</span></button>${rows.map(b=>`<button class="calendar-event ${b.status}" data-visit="${b.id}"><strong>${time(b.starts_at)}–${time(b.ends_at)}</strong><span>${esc(b.service_name)}</span><small>${esc(b.name)} · ${money(b.price)}</small>${b.attendance_state&&b.attendance_state!=='unknown'?`<span class="attendance-mini ${b.attendance_state}">${b.attendance_state==='coming'?'✓ Клиент придёт':'Клиент не сможет'}</span>`:''}</button>`).join('')}${blocks.map(b=>`<button class="calendar-block" data-unblock="${b.id}">${time(b.starts_at)}–${time(b.ends_at)}<br>${esc(b.label)}</button>`).join('')}${!rows.length&&!blocks.length?'<p class="calendar-free">Нет записей</p>':''}${S.calendar==='day'?freeTimeline(d,rows,blocks):''}</section>`}).join('');return `${heading('Расписание','Ваши встречи и свободное время.', '<button class="primary" data-manual>＋ Запись</button>')}<div class="calendar-toolbar"><div class="segmented">${[['day','День'],['week','Неделя'],['month','Месяц']].map(([v,t])=>`<button data-calendar="${v}" class="${S.calendar===v?'selected':''}">${t}</button>`).join('')}</div><div class="date-controls"><button class="secondary" data-shift="-1" aria-label="Назад">‹</button><input id="calendar-date" type="date" value="${S.date}" aria-label="Дата"><button class="secondary" data-shift="1" aria-label="Вперёд">›</button></div></div><div class="calendar-grid ${S.calendar}">${S.calendar==='month'?['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<div class="month-weekday">${d}</div>`).join('')+Array.from({length:(new Date(start+'T12:00Z').getUTCDay()+6)%7},()=>'<div class="calendar-day blank" aria-hidden="true"></div>').join(''):''}${cards}</div><p class="note">${esc(zoneLabel(zone()))} · обновляется автоматически. Блокировка не отменяет существующие записи.</p><button class="secondary" id="block-time">Закрыть время для записи</button>`}
function freeTimeline(d,rows,blocks){const hours=S.own.schedule[new Date(d+'T12:00Z').getUTCDay()];if(!hours)return '<div class="closed-day">Выходной день</div>';const list=[];for(const h of Array.isArray(hours)?hours:[hours]){let cursor=fromLocal(d,h.start,zone()),end=fromLocal(d,h.end,zone());for(const b of [...rows.map(b=>({...b,starts_at:b.starts_at-(S.own.buffer||0)*60,ends_at:b.ends_at+(S.own.buffer||0)*60})),...blocks].sort((a,b)=>a.starts_at-b.starts_at)){if(b.starts_at>cursor)list.push([cursor,Math.min(b.starts_at,end)]);cursor=Math.max(cursor,b.ends_at)}if(cursor<end)list.push([cursor,end])}return `<div class="free-timeline"><h3>Свободные промежутки</h3>${list.filter(([a,b])=>b>a&&b>Date.now()/1000).map(([a,b])=>`<button data-manual data-start="${a}">${time(a)}–${time(b)} <span>＋ Запись</span></button>`).join('')||'<p class="note">Нет свободных промежутков</p>'}</div>`}
function clientsPage(){return `${heading('Клиенты','Контакты, история и быстрые действия в одном месте.')}<label class="search-label clients-search">${icon('user')}<input id="client-search" type="search" placeholder="Имя или телефон" aria-label="Найти клиента"></label><div class="client-grid client-grid72">${S.clients.map(x=>{const canMessage=!!x.telegram_username;return `<article class="client-card72" data-search="${esc((x.name+' '+x.phone).toLowerCase())}"><div class="client-card72-main">${imageTag('',x.name,'small-avatar')}<div><h3>${esc(x.name)}</h3><p>${esc(x.phone)}</p><small>${x.visits} завершённых визитов${x.last_visit?' · '+dateLabel(date(x.last_visit)):''}</small></div><span class="client-status72 ${x.next_visit?'active':''}">${x.next_visit?'● '+dateLabel(date(x.next_visit)):'Нет будущей записи'}</span></div>${x.note?`<p class="client-note72">${esc(x.note)}</p>`:''}<div class="client-actions72">${canMessage?`<button class="client-write72" data-message-client="${esc(x.id)}">Написать</button>`:''}${x.phone?`<button class="client-call72" data-call="${esc(x.phone)}">Позвонить</button>`:''}<button class="client-open72" data-client="${esc(x.id)}">История</button><button class="client-open72" data-client="${esc(x.id)}" data-focus-note>Заметки</button></div></article>`}).join('')||empty('Здесь появятся ваши клиенты','Отправьте персональную ссылку. После первой записи клиент появится здесь.',button('Поделиться ссылкой','share'))}</div>`}
function more(){return `${heading('Мой кабинет',S.own.name)}<div class="more-grid">${[['services','grid','Услуги','Цены, описание и порядок'],['share','link','Персональная ссылка','Короткий адрес, QR-код и просмотр'],['analytics','calendar','Статистика','Завершённые и запланированные визиты'],['reviews','check','Отзывы','Оценка и отзывы после завершённых записей'],['settings','settings','Настройки','Профиль, место работы, рабочее время и правила'],['subscription','clock','Подписка',trialText(S.own)||'7 дней бесплатно · далее 590 ₽/месяц'],['profile','user','Помощь','Знакомство с Тактом и уведомления']].map(([p,i,t,d])=>`<button class="more-card ${p==='subscription'?'subscription-menu-card':''}" data-page="${p}"><span>${icon(i)}</span><div><h3>${t}</h3><p>${d}</p></div>${icon('arrow')}</button>`).join('')}</div>`}
function subscriptionPage(){const x=S.own.subscription||{},trial=x.status==='trial',expired=x.status==='expired',active=x.status==='active',activeDays=active&&x.paid_until?Math.max(0,Math.ceil((x.paid_until-Date.now()/1000)/86400)):null,status=trial?`Осталось ${x.days_left||0} дн.`:expired?'Доступ приостановлен':activeDays!==null?`Осталось ${activeDays} дн.`:'Подписка активна';return `${heading('Подписка','Спокойная онлайн-запись без комиссий с каждой встречи.')}<section class="subscription-v81 ${expired?'expired':''}"><div class="subscription-v81-hero"><div><span class="eyebrow">${trial?'ПРОБНЫЙ ПЕРИОД':expired?'ДОСТУП ПРИОСТАНОВЛЕН':'TAKT · ОДИН ТАРИФ'}</span><h2>${money(x.price??590)} <small>/ месяц</small></h2><p>Один понятный тариф для специалиста. Клиенты записываются бесплатно по вашей ссылке.</p></div><span class="subscription-status ${expired?'expired':''}">${esc(status)}</span></div><div class="subscription-v81-promise"><strong>Меньше переписки. Больше времени на работу.</strong><p>Takt показывает свободное время, принимает записи, напоминает о визите и хранит историю клиентов в одном месте.</p></div><div class="subscription-v81-features"><div><b>✓</b><span><strong>Онлайн-запись 24/7</strong><small>Клиент сам выбирает услугу и свободное время.</small></span></div><div><b>✓</b><span><strong>Календарь и клиенты</strong><small>Записи, контакты, заметки и история под рукой.</small></span></div><div><b>✓</b><span><strong>Telegram-уведомления</strong><small>Новые записи, подтверждения и напоминания автоматически.</small></span></div><div><b>✓</b><span><strong>Отзывы и подтверждение визита</strong><small>После визита клиент может оставить оценку и отзыв.</small></span></div><div><b>✓</b><span><strong>Без комиссии с записей</strong><small>${esc(x.tariff_description||'Ваш личный сервис онлайн-записи')}.</small></span></div><div><b>✓</b><span><strong>Поддержка и сохранность данных</strong><small>При паузе ваши услуги, клиенты и история не исчезают.</small></span></div></div>${expired?'<p class="subscription-safe">Ваш кабинет сохранён. Возобновите доступ — ничего настраивать заново не потребуется.</p>':''}${x.payment_url?`<a class="primary wide subscription-buy" href="${esc(x.payment_url)}" target="_blank" rel="noopener">${expired?'Возобновить доступ':'Продлить Takt'}</a>`:'<button type="button" class="secondary wide" id="support">Связаться с поддержкой</button>'}<p class="subscription-footnote">Клиенты пользуются Takt бесплатно. Данные сохраняются при паузе подписки.</p></section>`}
function servicesPage(){return `${heading('Мои услуги','Порядок карточек определяет порядок на странице клиента.','<button class="primary" data-edit-service="new">＋ Услуга</button>')}<div class="service-cards">${S.own.services.map((x,i)=>`<article class="service-card ${x.active?'':'hidden-service'}" draggable="true" data-service-card="${x.id}">${x.photo?`<img src="${esc(x.photo)}" alt="${esc(x.name)}">`:''}<span class="service-visibility">${x.active?'На странице записи':'Скрыта от клиентов'}</span><h2>${esc(x.name)}</h2><strong>${x.duration} мин · ${money(x.price)}</strong><p>${esc(x.description||'Добавьте описание — клиенту будет легче выбрать.')}</p><div class="actions"><button class="secondary" data-edit-service="${x.id}">Редактировать</button><button class="text-button" data-hide-service="${x.id}">${x.active?'Скрыть':'Показать'}</button><button class="sort-button" data-sort="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Поднять услугу">↑</button><button class="sort-button" data-sort="${i}" data-direction="1" ${i===S.own.services.length-1?'disabled':''} aria-label="Опустить услугу">↓</button></div></article>`).join('')||empty('Добавьте первую услугу','Она появится на вашей странице записи.','<button class="primary" data-edit-service="new">Добавить услугу</button>')}</div><p class="note">На компьютере карточки можно перетаскивать. На телефоне используйте стрелки.</p>`}
function sharePage(){return `${heading('Ваша ссылка для записи','Одна ссылка — прямой путь к вашим услугам.')}<section class="share-card"><div class="success-icon">${icon('link')}</div>${imageTag(S.own.photo,S.own.name)}<h2>${esc(S.own.name)}</h2><p>Разместите ссылку в Telegram, Instagram, WhatsApp, VK, Avito или на своём сайте.</p>${!S.own.username?'<p class="note">Выберите короткое имя для своей страницы ниже.</p>':''}<label>Персональная ссылка<input readonly value="${link(S.own.id)}" aria-label="Персональная ссылка"></label><div class="actions"><button class="primary" id="share-link">Поделиться</button><button class="secondary" id="copy-link">Скопировать</button><button class="secondary" id="qr-link">QR-код</button></div><button class="text-button" id="preview">Посмотреть глазами клиента ${icon('arrow')}</button><form id="handle-form"><label>Имя вашей страницы<input name="username" value="${esc(S.own.username||'')}" pattern="[a-zA-Z][a-zA-Z0-9-]{2,31}" minlength="3" maxlength="32" placeholder="davud" required autocapitalize="none"><small>Латинские буквы, цифры и дефис. Старые ссылки сохранятся.</small></label><div class="form-error" role="alert"></div><button class="secondary">Сохранить адрес</button></form></section>`}
const timezoneChoices=['Europe/Kaliningrad','Europe/Moscow','Europe/Samara','Asia/Yekaterinburg','Asia/Omsk','Asia/Krasnoyarsk','Asia/Irkutsk','Asia/Yakutsk','Asia/Vladivostok','Asia/Magadan','Asia/Kamchatka','Asia/Almaty','Asia/Baku','Asia/Tashkent'];
function timezoneField(value){return `<label>Часовой пояс<input type="hidden" name="timezone" value="${esc(value)}"><button class="picker-field" type="button" id="timezone-picker"><span>${esc(zoneLabel(value))}</span><small>${esc(value)}</small></button><small>В этом поясе клиент видит время записи. Уже созданные встречи сохраняют свой момент времени.</small></label>`}
function timezonePicker(){const current=document.querySelector('[name="timezone"]')?.value||zone();const all=[...new Set([current,...timezoneChoices])];openSheet('Часовой пояс',`<label class="search-label timezone-search">${icon('search')}<input id="timezone-search" type="search" placeholder="Найти город или пояс" autocomplete="off"></label><div class="timezone-list">${all.map(z=>`<button type="button" class="timezone-option ${z===current?'selected':''}" data-timezone="${esc(z)}" data-search="${esc((zoneLabel(z)+' '+z).toLowerCase())}"><span>${esc(zoneLabel(z))}</span><small>${esc(z)}</small>${z===current?'✓':''}</button>`).join('')}</div>`)}
const starText=n=>'★★★★★'.slice(0,Math.max(0,Math.min(5,Number(n)||0)));
function reviewList(items){return items?.length?`<div class="review-list">${items.map(r=>`<article class="review-card"><div><strong>${esc(r.client_name||'Клиент')}</strong><span>${starText(r.rating)}</span></div>${r.text?`<p>${esc(r.text)}</p>`:''}<small>${esc(r.service_name||'')} · ${new Date(r.created_at*1000).toLocaleDateString(localeFor(S.language))}</small></article>`).join('')}</div>`:empty('Отзывов пока нет','После первого завершённого визита клиент сможет поделиться впечатлением.')}
function reviewsPage(){const summary=S.own.reviews||{average:0,count:0};return `${heading('Отзывы','Отзывы только после завершённых записей.')}<section class="reviews-summary"><div><strong>${Number(summary.average||0).toFixed(1)}</strong><span>★</span></div><p>${summary.count||0} отзывов</p></section>${reviewList(S.reviews)}`}
function clientReviews(x){const r=x.reviews||{average:0,count:0,items:[]};if(!r.count)return '';return `<section class="public-reviews"><button type="button" data-all-reviews="${esc(x.id)}"><div><strong>${Number(r.average||0).toFixed(1)} ★</strong><span>${r.count} отзывов</span></div><span>Все отзывы →</span></button>${reviewList(r.items)}</section>`}
async function showReviews(id){openSheet('Отзывы',skeleton());try{const r=await api('/v7/reviews?company='+encodeURIComponent(id)+'&limit=100');openSheet(`Отзывы · ${r.count}`,`<section class="reviews-summary compact"><div><strong>${Number(r.average||0).toFixed(1)}</strong><span>★</span></div><p>${r.count} отзывов</p></section>${reviewList(r.items)}`)}catch(e){openSheet('Отзывы',`<p>${esc(translateText(e.message,S.language))}</p>`)}}
function reviewEditor(id){const b=S.bookings.find(x=>x.id===id);if(!b)return;if(b.review_rating){toast('Вы уже оставили отзыв');return}openSheet('Оставить отзыв',`<form id="review-form" data-booking="${esc(id)}"><p class="dialog-sub">${esc(b.service_name)} · ${dateLabel(date(b.starts_at))}</p><fieldset class="rating-field"><legend>Как всё прошло?</legend>${[5,4,3,2,1].map(n=>`<label><input type="radio" name="rating" value="${n}" required><span>${n} ★</span></label>`).join('')}</fieldset><label>Комментарий · по желанию<textarea name="text" maxlength="1200" placeholder="Расскажите о впечатлении"></textarea></label><div class="form-error" role="alert"></div><button class="primary wide" type="submit">Отправить отзыв</button></form>`)}
function settingsPage(){const x=S.own;return `${heading('Настройки','Все параметры вашего кабинета — по понятным разделам.','<button class="secondary" id="preview">Глазами клиента</button>')}<section class="editor-card settings-card"><form id="settings-form"><details class="settings-section" open><summary>Профиль <small>Имя, описание и контакты</small></summary>${photoField('settings',x.photo)}<label>Имя или название<input name="name" value="${esc(x.name)}" required minlength="2" maxlength="80"></label><div class="form-grid"><label>Профессия<input name="profession" value="${esc(x.profession||'')}" maxlength="80" placeholder="Например, барбер"></label><label>Сфера<select name="category">${Object.entries(cats).map(([v,t])=>`<option value="${v}" ${x.category===v?'selected':''}>${t}</option>`).join('')}</select></label></div><label>Описание<textarea name="tagline" maxlength="160">${esc(x.tagline)}</textarea></label><div class="form-grid"><label>Телефон<input name="phone" value="${esc(x.phone)}" maxlength="24" type="tel"></label><label>Telegram<input name="telegram" value="${esc(x.telegram||'')}" maxlength="33" placeholder="@username" autocapitalize="none"></label></div></details><details class="settings-section"><summary>Место работы <small>Адрес и как вас найти</small></summary><label>Формат работы<select name="format">${[['salon','У меня / в салоне'],['visit','Выезд к клиенту'],['online','Онлайн']].map(([v,t])=>`<option value="${v}" ${x.format===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Адрес<input name="address" value="${esc(x.address)}" maxlength="200" placeholder="Улица, дом"></label><div class="location-grid"><label>Салон / студия<input name="venue_name" value="${esc(x.venue_name||'')}" maxlength="80" placeholder="Название места"></label><label>Этаж<input name="floor" value="${esc(x.floor||'')}" maxlength="30" placeholder="Например, 2 этаж"></label><label>Кабинет / квартира<input name="room" value="${esc(x.room||'')}" maxlength="40" placeholder="Например, 205"></label><label>Вход / подъезд<input name="entrance" value="${esc(x.entrance||'')}" maxlength="100" placeholder="Например, подъезд 2"></label><label class="wide">Как пройти<textarea name="directions" maxlength="500" placeholder="Короткий ориентир для клиента">${esc(x.directions||'')}</textarea></label><label class="wide">Ссылка на карту<input name="map_url" type="url" value="${esc(x.map_url||'')}" maxlength="500" placeholder="https://..."></label></div></details><details class="settings-section"><summary>Расписание <small>Рабочие дни, часы и перерывы</small></summary>${scheduleFields(x.schedule)}</details><details class="settings-section"><summary>Выходные и отпуск <small>Закрытые даты и часы</small></summary><p class="note">Закройте один день или любой период. Существующие встречи сохраняются.</p><button type="button" class="secondary" id="block-time">Закрыть период</button></details><details class="settings-section"><summary>Правила записи <small>Условия для клиентов</small></summary><div class="form-grid"><label>За сколько заранее можно записаться<select name="min_notice">${[[0,'Без ограничения'],[30,'30 минут'],[60,'1 час'],[120,'2 часа'],[180,'3 часа'],[360,'6 часов'],[720,'12 часов'],[1440,'24 часа']].map(([v,t])=>`<option value="${v}" ${x.min_notice===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Запись вперёд<select name="horizon">${[[7,'7 дней'],[14,'14 дней'],[30,'1 месяц'],[60,'2 месяца'],[90,'3 месяца · стандарт'],[120,'4 месяца'],[180,'6 месяцев']].map(([v,t])=>`<option value="${v}" ${Number(x.horizon)===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Перерыв между клиентами, минут<input type="number" name="buffer" value="${x.buffer}" min="0" max="240" required></label><label>Отмена не позднее чем за, часов<input type="number" name="cancel_hours" value="${x.cancel_hours}" readonly required><small>Единое правило Takt</small></label></div><label class="toggle-row"><span>Разрешить клиентам перенос</span><input type="checkbox" name="allow_reschedule" ${x.allow_reschedule?'checked':''}></label><p class="note">Срок отмены применяется и к переносу. Позднюю отмену клиент согласовывает с вами.</p></details><details class="settings-section"><summary>Уведомления <small>Что присылать в Telegram</small></summary>${[['created','Новая запись'],['cancelled','Отмена записи'],['moved','Перенос записи'],['reminders','Подтверждение визита клиентом за 24 часа'],['client_2h','Клиенту за 2 часа'],['master_2h','Мне за 2 часа до клиента'],['client_events','Клиенту: подтверждение, отмена и перенос'],['daily_summary','Итоги моего дня'],['master_reminder','Дополнительно: мне за 1 час'],['summary','Дополнительно: утренняя сводка в 08:00']].map(([k,t])=>`<label class="toggle-row"><span>${t}</span><input type="checkbox" name="notify_${k}" ${x.notifications?.[k]?'checked':''}></label>`).join('')}<label>Во сколько присылать итоги дня<input type="time" name="summary_time" value="${esc(x.summary_time||'20:00')}" required><small>В вашем часовом поясе. По умолчанию — 20:00.</small></label><p class="note">За 24 часа Takt просит клиента подтвердить визит. Если ответа нет, за 2 часа напомнит ещё раз.</p><div id="delivery-status" class="note"></div></details><details class="settings-section"><summary>Часовой пояс <small>Время ваших записей</small></summary>${timezoneField(x.timezone)}</details><details class="settings-section settings-accent"><summary>Интерфейс <small>Язык и тема приложения</small></summary>${languageControl()}${themeControl()}</details><details class="settings-section settings-accent"><summary>Помощь <small>Ответы, документы и поддержка</small></summary><div class="settings-links-v8"><button type="button" data-page="help">Вопросы и ответы</button><button type="button" data-page="legal">Документы и конфиденциальность</button><button type="button" id="support">Поддержка</button></div></details><div class="form-error" role="alert"></div><div class="settings-save"><button class="primary wide" type="submit">Сохранить настройки</button></div></form></section><section class="settings-system settings-system-v8"><div><strong>Takt 10.0</strong><span>Версия приложения</span></div><button class="guide-highlight" id="guide">Как это работает</button></section>`}
function languageControl(){return `<div class="preference-control"><span>Язык приложения</span><div class="choice-pills">${LANGUAGES.filter(([code])=>!S.config||S.config.languages.includes(code)).map(([code,flag,name])=>`<button type="button" data-language="${code}" class="${S.language===code?'selected':''}">${flag} ${name}</button>`).join('')}</div></div>`}
function themeControl(){const mode=S.appSettings?.theme||storedTheme();return `<div class="preference-control"><span>Тема оформления</span><div class="choice-pills">${[['system','Как в системе'],['light','Светлая'],['dark','Тёмная']].map(([v,t])=>`<button type="button" data-theme="${v}" class="${mode===v?'selected':''}">${t}</button>`).join('')}</div></div>`}
function helpPage(){const rows=faqCopy(S.language);return `${heading('Вопросы и ответы','Короткие ответы по работе Takt.')}<div class="faq-list">${rows.map(([q,ans])=>`<details class="faq-card"><summary>${esc(q)}</summary><p>${esc(ans)}</p></details>`).join('')}</div><section class="help-actions-v8"><button class="primary" id="support">Написать в поддержку</button><button class="secondary" data-page="legal">Документы</button></section>`}
function legalPage(){const docs=['policy','consent','terms'];return `${heading('Документы и конфиденциальность','Документы всегда доступны в настройках клиента и специалиста.')}<div class="legal-cards">${docs.map(type=>{const [title,paragraphs]=legalDoc(type,S.language);return `<article class="legal-card"><span class="eyebrow">Takt</span><h2>${esc(title)}</h2><p>${esc(paragraphs[0])}</p>${S.config?.documents?.[type]?.urls?.[S.language]?`<a class="secondary" href="${esc(S.config.documents[type].urls[S.language])}" target="_blank" rel="noopener">Открыть документ</a>`:`<button class="secondary" data-legal="${type}">Открыть документ</button>`}</article>`}).join('')}</div><p class="legal-version">Принято: ${S.appSettings?.consent_at?new Date(S.appSettings.consent_at*1000).toLocaleDateString(localeFor(S.language)):'—'} · версия ${esc(S.appSettings?.versions?.policy||'2026-10-05-v2')}</p>`}
function analyticsPage(){const done=S.bookings.filter(b=>b.status==='done'),planned=S.bookings.filter(future);return `${heading('Статистика','По последним 500 записям вашего кабинета.')}<section class="today-summary"><div><span>Завершено визитов</span><strong>${done.length}</strong></div><div><span>Стоимость завершённых</span><strong>${money(done.reduce((a,b)=>a+b.price,0))}</strong></div><div><span>Ожидаемая стоимость</span><strong>${money(planned.reduce((a,b)=>a+b.price,0))}</strong></div></section><section class="editor-card"><h2>Услуги, которые выбирают</h2>${S.own.services.map(s=>{const n=done.filter(b=>b.service_id===s.id).length;return `<div class="analytics-row"><span>${esc(s.name)}</span><strong>${n} визитов</strong><meter value="${n}" max="${Math.max(done.length,1)}"></meter></div>`}).join('')||'<p>Добавьте услуги, чтобы начать.</p>'}<p class="note">Это стоимость услуг по записям, а не отчёт об оплатах. Онлайн-оплаты не подключены.</p></section>`}
function clientPage(){const x=S.tenant;if(!x)return empty('Нужна ссылка специалиста','Откройте приглашение вашего мастера. Если ссылка не работает, попросите прислать новую.');const reviews=S.config?.flags?.reviews===false?{average:0,count:0,items:[]}:x.reviews||{average:0,count:0,items:[]},route=x.map_url||(x.address?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(x.address):''),place=x.format==='visit'?'Специалист работает с выездом':x.format==='online'?'Встреча проходит онлайн':x.address||'Место встречи уточнит специалист',rows=[[x.address&&'Адрес',x.address],[x.venue_name&&'Место',x.venue_name],[x.floor&&'Этаж',x.floor],[x.room&&'Кабинет / квартира',x.room],[x.entrance&&'Вход / подъезд',x.entrance],[x.directions&&'Как пройти',x.directions]].filter(r=>r[0]&&r[1]),location=x.format==='salon'&&rows.length?`<section class="location-card client-location"><div class="client-section-title"><div><span class="eyebrow">МЕСТО ВСТРЕЧИ</span><h2>Как вас найти</h2></div>${route?`<a class="text-button" href="${esc(route)}" target="_blank" rel="noopener">Маршрут →</a>`:''}</div><div class="location-details">${rows.map(([label,value])=>`<div class="location-detail"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div><div class="client-location-actions">${route?`<a class="secondary" href="${esc(route)}" target="_blank" rel="noopener">${icon('pin')} Построить маршрут</a>`:''}${x.telegram?`<a class="secondary" href="https://t.me/${esc(x.telegram)}" target="_blank" rel="noopener">Связаться</a>`:''}</div></section>`:'';return `<section class="specialist-brief client-premium-head"><div class="specialist-identity">${imageTag(x.photo,x.name)}<div class="specialist-copy"><span class="eyebrow">${esc(x.profession||cats[x.category]||'Специалист')}</span><h1>${esc(x.name)}</h1>${x.tagline?`<p>${esc(x.tagline)}</p>`:''}</div>${reviews.count?`<button class="client-rating" data-all-reviews="${esc(x.id)}"><strong>${Number(reviews.average||0).toFixed(1)} ★</strong><span>${reviews.count} отзывов</span></button>`:''}</div><div class="specialist-quick client-contact-row"><span class="specialist-place">${icon('pin')}<span>${esc(place)}</span></span><div>${x.telegram?`<a class="secondary compact" href="https://t.me/${esc(x.telegram)}" target="_blank" rel="noopener">Telegram</a>`:''}${x.phone?`<a href="tel:${esc(x.phone.replace(/[^+0-9]/g,''))}" class="secondary compact">Позвонить</a>`:''}</div></div><div id="client-next" class="client-next"></div></section><div class="section-heading client-services-heading"><div><span class="eyebrow">УСЛУГИ</span><h2>Выберите услугу</h2></div><span>${x.services.length}</span></div><div class="client-services premium-services">${x.services.map(s=>`<article class="client-service premium-service">${s.photo?`<img src="${esc(s.photo)}" alt="${esc(s.name)}">`:''}<div class="service-copy"><h3>${esc(s.name)}</h3>${s.description?`<p>${esc(s.description)}</p>`:''}<div class="service-meta"><span>${s.duration} мин</span><strong>${money(s.price)}</strong></div></div><button class="primary" data-book="${s.id}">Записаться</button></article>`).join('')||empty('Услуги пока не опубликованы','Свяжитесь со специалистом, чтобы уточнить возможность записи.')}<p class="note client-policy">${'Самостоятельная отмена — больше чем за '+x.cancel_hours+' ч до визита.'} · ${esc(zoneLabel(x.timezone))}</p></div>${reviews.count?`<section class="client-review-preview"><div class="client-section-title"><div><span class="eyebrow">ОТЗЫВЫ</span><h2>${Number(reviews.average||0).toFixed(1)} ★ · ${reviews.count}</h2></div><button class="text-button" data-all-reviews="${esc(x.id)}">Все отзывы →</button></div>${reviewList((reviews.items||[]).slice(0,2))}</section>`:''}${location}`}
function myBookings(){if(!S.me)return login();const all=S.bookings.filter(b=>!S.tenant||b.company_id===S.tenant.id),rows=all.filter(b=>S.tab==='upcoming'?future(b):!future(b));return `${heading('Мои записи',S.tenant?.name||'Ваши визиты')}<div class="segmented">${[['upcoming','Предстоящие'],['history','История']].map(([v,t])=>`<button data-tab="${v}" class="${S.tab===v?'selected':''}">${t}</button>`).join('')}</div><div class="visits">${rows.sort((a,b)=>S.tab==='upcoming'?a.starts_at-b.starts_at:b.starts_at-a.starts_at).map(b=>bookingCard(b)).join('')||empty(S.tab==='upcoming'?'Здесь появится ваша запись':'История начнётся с первого визита','Выберите услугу и удобное время у своего специалиста.',button('Записаться','client'))}</div>`}
function profile(){const app=S.appSettings||{};return `${heading(isClient()?'Мой профиль':'Мой кабинет',isClient()?'Настройки клиента и ваши визиты.':'Аккаунт, интерфейс и помощь Takt.')}<section class="editor-card profile-v8">${imageTag(isClient()?'':S.own?.photo,isClient()?S.me?.name:S.own?.name)}<div><span class="eyebrow">${isClient()?'КЛИЕНТ':'СПЕЦИАЛИСТ'}</span><h2>${esc((isClient()?S.me?.name:S.own?.name)||'Гость')}</h2><p class="note">${isClient()?'Ваши записи доступны только вам и выбранному специалисту.':'Вы управляете своим пространством, услугами и клиентами.'}</p></div></section><section class="editor-card profile-settings-v8"><h3>Интерфейс</h3>${languageControl()}${themeControl()}</section><section class="profile-link-grid"><button data-page="help"><strong>Вопросы и ответы</strong><span>Подсказки по работе Takt</span></button><button data-page="legal"><strong>Документы и конфиденциальность</strong><span>${app.consent_at?'Согласие сохранено':'Открыть документы'}</span></button><button id="support"><strong>Поддержка</strong><span>Сообщение получит администратор Takt</span></button></section>${!isClient()?'<section class="profile-link-grid"><button data-page="settings"><strong>Настройки</strong><span>Профиль, расписание и правила</span></button><button data-page="subscription"><strong>Подписка</strong><span>Тариф и срок доступа</span></button></section>':''}${!isClient()&&S.me?.owner?'<section class="editor-card"><h3>Подключение Telegram · владелец</h3><button class="secondary" id="connect-bot">Обновить настройки бота</button></section>':''}`}
function openSheet(title,html,back=''){sheet.scrollTop=0;const backButton=back?(back==='close'?'<button class="dialog-back" data-close aria-label="Назад">← Назад</button>':`<button class="dialog-back" id="${back}" aria-label="Назад">← Назад</button>`):'';sheet.innerHTML=`<div class="sheet-grip"></div><div class="dialog-head ${back?'has-back':''}">${backButton}<h2>${esc(title)}</h2><button class="close" data-close aria-label="Закрыть">×</button></div>${html}`;localizeDOM(sheet,S.language);if(!sheet.open)sheet.showModal()}
function serviceEditor(id){const s=S.own.services.find(x=>x.id===id)||{name:'',description:'',price:1500,duration:60,photo:'',active:1,position:S.own.services.length};S.photo=s.photo;openSheet(id==='new'?'Новая услуга':'Редактировать услугу',`<form id="service-form" data-id="${s.id||''}" data-key="${crypto.randomUUID()}">${photoField('service',s.photo)}<label>Название<input name="name" value="${esc(s.name)}" required minlength="2" maxlength="120"></label><label>Описание<textarea name="description" maxlength="700">${esc(s.description)}</textarea></label><div class="form-grid"><label>Стоимость, ₽<input name="price" type="number" value="${s.price}" min="0" max="1000000" required></label><label>Длительность, мин<input name="duration" type="number" value="${s.duration}" min="15" max="480" step="5" required></label></div><input type="hidden" name="position" value="${s.position}"><input type="hidden" name="active" value="${s.active}"><div class="form-error" role="alert"></div><button class="primary wide">Сохранить услугу</button></form>`)}
function blockEditor(){openSheet('Закрыть время',`<p class="note">Выберите часы, выходной или отпуск. В периоде не должно быть активных записей.</p><form id="block-form"><label class="toggle-row"><span>Закрыть дни целиком</span><input name="whole_days" type="checkbox"></label><div class="form-grid"><label>Начало<input type="date" name="date" min="${day()}" value="${S.date<day()?day():S.date}" required><input type="time" name="start" value="09:00" required></label><label>Окончание<input type="date" name="end_date" min="${day()}" value="${S.date<day()?day():S.date}" required><input type="time" name="end" value="20:00" required></label></div><label>Причина · только для вас<input name="label" maxlength="80" placeholder="Например, отпуск"></label><div class="form-error" role="alert"></div><button class="primary wide">Закрыть время</button></form>`)}
async function manualEditor(reset=true){if(!S.own.services.some(s=>s.active)){toast('Сначала добавьте доступную услугу');return}if(reset){manualClient=null;manualNewClient={name:'',phone:''};booking=null}const targetDate=manualDate||S.date||day();openSheet('Кого записать?',skeleton());try{S.clients=await api('/v2/clients?company='+S.own.id);openSheet('Кого записать?',`<p class="dialog-sub manual-date-hint">Дата: ${dateLabel(targetDate)} · выберите клиента, затем услугу и свободное время.</p><button class="primary wide" id="manual-new">＋ Новый клиент</button><label class="search-label"><input id="manual-search" placeholder="Имя или телефон" aria-label="Найти клиента"></label><div class="manual-clients">${S.clients.map(x=>`<button class="more-card" data-manual-client="${esc(x.id)}" data-search="${esc((x.name+' '+x.phone).toLowerCase())}"><div><h3>${esc(x.name)}</h3><p>${esc(x.phone)}</p></div>${icon('arrow')}</button>`).join('')||'<p class="note">Добавьте первого клиента по имени и телефону.</p>'}</div>`)}catch(e){openSheet('Не удалось загрузить клиентов',`<p>${esc(translateText(e.message,S.language))}</p><button class="primary" data-manual>Повторить</button>`)}}
function manualNewClientEditor(){openSheet('Новый клиент',`<form id="manual-client-form"><label>Имя<input name="name" value="${esc(manualNewClient.name)}" required minlength="2" maxlength="80" autocomplete="name"></label><label>Телефон<input name="phone" type="tel" value="${esc(manualNewClient.phone)}" required minlength="10" maxlength="24" autocomplete="tel"></label><div class="form-error" role="alert"></div><button class="primary wide">Выбрать услугу</button></form>`,'manual-back-clients')}
function manualServices(){openSheet('Выберите услугу',`<p class="note">Клиент: ${esc(manualClient.name)}</p><div class="manual-services">${S.own.services.filter(s=>s.active).map(s=>`<button class="more-card" data-manual-service="${s.id}"><div><h3>${esc(s.name)}</h3><p>${s.duration} мин · ${money(s.price)}</p></div>${icon('arrow')}</button>`).join('')}</div>`,'manual-back-clients')}
async function startBooking(id,manual=false,move=null){if(!S.me){openSheet('Вход через Telegram',login());return}const tenant=manual?S.own:S.tenant,s=tenant?.services.find(x=>x.id===id)||move&&{id:move.service_id,name:move.service_name,duration:(move.ends_at-move.starts_at)/60,price:move.price};if(!tenant||!s)return;const previous=manual&&booking?.manual&&!booking.move?booking:null,sameClient=previous&&((previous.client_id&&previous.client_id===manualClient?.id)||(!previous.client_id&&previous.phone===manualClient?.phone));booking={tenant,s,manual,move,key:crypto.randomUUID(),step:0,date:manual?(previous?.date||manualDate):day(),at:manual?(previous?.at||null):null,name:manual?manualClient?.name||previous?.name||'':S.me.name,phone:manual?manualClient?.phone||previous?.phone||'':'',details:manual&&sameClient?previous.details||'':'',client_id:manual?manualClient?.id:undefined,known:manual&&!!manualClient,month:manual?(previous?.month||(previous?.date||manualDate).slice(0,7)):day().slice(0,7),availability:{}};if(!manual&&!move){try{const contact=await api('/v4/contact?company='+tenant.id);if(contact.phone){booking.name=contact.name;booking.phone=contact.phone;booking.known=true}}catch{}}await bookingSheet()}
function bookingCalendar(b){const start=b.month+'-01',n=new Date(Number(b.month.slice(0,4)),Number(b.month.slice(5)),0).getDate(),offset=(new Date(start+'T12:00Z').getUTCDay()+6)%7;return `<div class="booking-calendar"><div class="calendar-month-head"><button class="secondary" data-book-month="-1" aria-label="Предыдущий месяц" ${b.month<=day().slice(0,7)?'disabled':''}>‹</button><strong>${new Date(start+'T12:00Z').toLocaleDateString(localeFor(S.language),{month:'long',year:'numeric'})}</strong><button class="secondary" data-book-month="1" aria-label="Следующий месяц" ${b.month>=day(b.tenant.horizon||90).slice(0,7)?'disabled':''}>›</button></div><div class="booking-month-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(t=>`<span>${t}</span>`).join('')}${Array.from({length:offset},()=>'<span></span>').join('')}${Array.from({length:n},(_,i)=>{const d=shift(start,i),info=b.availability[d],allowed=d>=day()&&d<=day(b.tenant.horizon||90)&&info?.count>0;return `<button data-book-date="${d}" aria-label="${dateLabel(d)}${allowed?' · есть время':' · недоступно'}" class="${d===b.date?'selected':''}" ${allowed?'':'disabled'}>${i+1}${allowed?'<i></i>':''}</button>`}).join('')}</div></div>`}
async function bookingSheet(){const epoch=++calendarRequest,b=booking;if(!b)return;if(b.step===0){const back=b.manual&&!b.move?'manual-back-services':'close';openSheet(b.move?'Перенести запись':'Выберите дату и время',`<p class="dialog-sub">${esc(b.s.name)} · ${b.s.duration} мин · ${money(b.s.price)}</p><div id="booking-calendar">${skeleton()}</div><div id="available-slots" class="slots">${skeleton()}</div><p class="note">${esc(zoneLabel(zone()))}</p><div class="sticky-actions"><button class="primary wide" id="booking-next" disabled>${b.move?'Перенести на это время':'Продолжить'}</button></div><div class="form-error" role="alert"></div>`,back);try{const dates=await api('/availability?company='+b.tenant.id+'&service='+b.s.id+'&date='+b.month+'-01&days=31'+(b.move?'&booking='+b.move.id:''));if(epoch!==calendarRequest||booking!==b||!sheet.open)return;for(const d of dates)b.availability[d.date]=d;if(!b.date.startsWith(b.month))b.date=dates.find(d=>d.date.startsWith(b.month)&&d.count>0)?.date||b.month+'-01';sheet.querySelector('#booking-calendar').innerHTML=bookingCalendar(b);await loadSlots()}catch(e){if(epoch===calendarRequest&&booking===b&&sheet.open){sheet.querySelector('#available-slots').innerHTML='<p>Не удалось загрузить данные</p><button class="secondary" id="retry-slots">Повторить</button>';sheet.querySelector('#booking-calendar').innerHTML=''}}}
else if(b.step===1){openSheet('Контакты для встречи',`<p class="dialog-sub">${dateLabel(b.date)} · ${time(b.at)} · ${esc(b.s.name)}</p><form id="booking-contact"><label>Имя<input name="name" value="${esc(b.name)}" minlength="2" maxlength="80" required autocomplete="given-name"></label><label>Телефон<input name="phone" type="tel" value="${esc(b.phone)}" minlength="10" maxlength="24" required autocomplete="tel"></label><label>${b.tenant.category==='cleaning'?'Адрес и площадь':b.tenant.category==='auto'?'Автомобиль и задача':'Комментарий'}<textarea name="details" maxlength="1200" ${['cleaning','auto'].includes(b.tenant.category)?'required minlength="5"':''}>${esc(b.details)}</textarea></label><label class="consent"><input type="checkbox" required><span>Передать контакты ${b.manual?'для оформления записи':'специалисту для обработки моей заявки'}.</span></label><div class="form-error" role="alert"></div><button class="primary wide">Проверить запись</button></form>`,'booking-back')}
else openSheet('Ваша запись',`<div class="booking-review"><span class="eyebrow">${esc(b.tenant.name)}</span><h2>${esc(b.s.name)}</h2><div><span>Дата и время</span><strong>${dateLabel(b.date)}, ${time(b.at)}</strong></div><div><span>Длительность</span><strong>${b.s.duration} мин</strong></div><div><span>Стоимость</span><strong>${money(b.s.price)}</strong></div><div><span>Клиент</span><strong>${esc(b.name)}</strong></div><div><span>Телефон</span><strong>${esc(b.phone)}</strong></div><p class="note">Без онлайн-оплаты. ${b.manual?'Запись появится в вашем календаре.':'Специалист подтвердит вашу заявку.'}</p><div class="form-error" role="alert"></div><button class="primary wide" id="booking-submit">${b.manual?'Добавить запись':'Подтвердить запись'}</button></div>`,'booking-back')}
let slotRequest=0,calendarRequest=0;
async function loadSlots(){const n=++slotRequest,b=booking,selectedAt=b.at;try{const slots=await api('/slots?company='+b.tenant.id+'&service='+b.s.id+'&date='+b.date+(b.move?'&booking='+b.move.id:''));if(n!==slotRequest||booking!==b||!sheet.open)return;const selectedValid=selectedAt&&slots.includes(selectedAt);b.at=selectedValid?selectedAt:null;sheet.querySelector('#available-slots').innerHTML=slots.length?slots.map(t=>`<button class="slot ${selectedValid&&t===selectedAt?'active':''}" data-slot="${t}">${time(t)}</button>`).join(''):'<div class="no-slots"><h3>На этот день свободного времени нет</h3><p>Ищем ближайший доступный день…</p></div>';const nextButton=sheet.querySelector('#booking-next');if(nextButton)nextButton.disabled=!selectedValid;if(!slots.length){const next=await api('/next-slot?company='+b.tenant.id+'&service='+b.s.id+'&date='+b.date+(b.move?'&booking='+b.move.id:''));if(n!==slotRequest||booking!==b||!sheet.open)return;sheet.querySelector('#available-slots').innerHTML=next.date?`<div class="no-slots"><h3>На этот день свободного времени нет</h3><p>Ближайшее время: ${dateLabel(next.date)} · ${time(next.starts_at)}</p><button class="secondary" data-book-date="${next.date}">Показать</button></div>`:'<div class="no-slots"><h3>Все доступные даты заняты</h3><p>Свяжитесь со специалистом, чтобы подобрать время.</p></div>'}}catch(e){if(n===slotRequest&&sheet.open)sheet.querySelector('#available-slots').textContent=translateText(e.message,S.language)}}
async function submitBooking(el){el.disabled=true;try{if(!booking.manual)await requestMessages();const b=booking;if(b.move)await post('/v2/reschedule',{id:b.move.id,starts_at:b.at});else await post('/bookings',{company_id:b.tenant.id,service_id:b.s.id,starts_at:b.at,name:b.name,phone:b.phone,details:b.details,request_key:b.key,manual:b.manual,client_id:b.manual?b.client_id:undefined});openSheet('Готово',`<section class="success"><div class="success-icon">${icon('check')}</div><h2>${b.move?'Запись перенесена':'Вы записаны'}</h2><p>${esc(b.tenant.name)}<br>${dateLabel(b.date)} · ${time(b.at)} · ${esc(zoneLabel(zone()))}</p><button class="primary wide" id="booking-finished">${b.manual?'Открыть календарь':'Мои записи'}</button>${!b.manual?'<p class="note">Подтверждение и напоминания отправляются автоматически в Telegram.</p>':''}</section>`);tg?.HapticFeedback?.notificationOccurred('success')}catch(e){if(e.status===409){booking.step=0;booking.availability={};await bookingSheet();sheet.querySelector('.form-error').textContent='Это время только что заняли. Выберите другое свободное окно.'}else{sheet.querySelector('.form-error').textContent=translateText(e.message,S.language);el.disabled=false}}}
function visitActions(id){const b=S.bookings.find(x=>x.id===id);if(!b)return;const admin=!isClient(),allowed=active(b)&&(admin||b.starts_at>Date.now()/1000+(S.tenant?.cancel_hours||0)*3600),canMessage=admin&&/^[0-9]+$/.test(String(b.user_id)),att=admin&&active(b)?attendanceInfo(b):null;openSheet('Детали записи',`<section class="visit-detail-v81"><div class="visit-detail-head"><div><span class="eyebrow">${admin?'КЛИЕНТ':'ЗАПИСЬ'}</span><h2>${esc(b.service_name)}</h2><p>${dateLabel(date(b.starts_at))} · ${time(b.starts_at)}–${time(b.ends_at)}</p></div><span class="badge ${b.status}">${labels[b.visit_outcome||b.status]||labels[b.status]}</span></div><div class="visit-detail-grid"><div><span>${admin?'Клиент':'Специалист'}</span><strong>${esc(admin?b.name:b.company_name||S.tenant?.name||'Специалист')}</strong></div>${admin&&b.phone?`<div><span>Телефон</span><strong>${esc(b.phone)}</strong></div>`:''}<div><span>Стоимость</span><strong>${money(b.price)}</strong></div><div><span>Длительность</span><strong>${Math.max(1,Math.round((b.ends_at-b.starts_at)/60))} мин</strong></div></div>${att?`<div class="visit-detail-attendance"><span class="attendance visit-confirmation ${att[0]}">${att[1]}</span>${att[2]?`<small>${att[2]}</small>`:''}</div>`:''}${b.details?`<div class="visit-detail-note"><span>Комментарий</span><p>${esc(b.details)}</p></div>`:''}</section><div class="sheet-actions visit-detail-actions">${!admin&&b.status==='done'&&b.visit_outcome!=='no_show'&&!b.review_rating?`<button class="primary" data-review="${b.id}">⭐ Оставить отзыв</button>`:''}${admin&&b.status==='pending'?`<button class="primary" data-status="confirmed" data-id="${id}">Подтвердить</button>`:''}${admin&&b.status==='confirmed'?`<button class="primary" data-status="done" data-id="${id}">Завершить визит</button><button class="danger" data-status="no_show" data-id="${id}">Клиент не пришёл</button>`:''}${canMessage?`<button class="secondary" data-message-client="${esc(b.user_id)}">Написать</button>`:''}${admin&&b.phone?`<button class="secondary" data-call="${esc(b.phone)}">Позвонить</button>`:''}${!admin&&active(b)&&!allowed?`<div class="late-cancel"><p>Поздняя отмена согласовывается со специалистом.</p>${S.tenant?.telegram?`<a class="secondary" href="https://t.me/${esc(S.tenant.telegram)}" target="_blank" rel="noopener">Написать специалисту</a>`:S.tenant?.phone?`<a class="secondary" href="tel:${esc(S.tenant.phone.replace(/[^+0-9]/g,''))}">Позвонить</a>`:''}</div>`:''}${allowed?`${admin||S.tenant?.allow_reschedule?`<button class="secondary" data-move="${id}">Перенести</button>`:''}<button class="danger" data-cancel="${id}">Отменить запись</button>`:''}</div><div class="form-error" role="alert"></div>`)}
function supportEditor(){openSheet('Поддержка Takt',`<form id="support-form"><p class="dialog-sub">Сообщение получит только администратор Takt.</p><label>Опишите проблему<textarea name="message" maxlength="1500" minlength="5" required placeholder="Что произошло и что вы ожидали увидеть?"></textarea></label><div class="form-error" role="alert"></div><button class="danger wide" type="submit">Отправить в поддержку</button></form>`)}
async function clientMessageEditor(id){let x=S.clients.find(c=>String(c.id)===String(id));if(!x&&S.own)try{S.clients=await api('/v2/clients?company='+S.own.id);x=S.clients.find(c=>String(c.id)===String(id))}catch{}if(!x){toast('Клиент не найден');return}if(!x.telegram_username){toast('Личный Telegram клиента недоступен. Используйте телефон.');return}openTelegramClient(x.telegram_username)}
function callClient(phone){const clean=String(phone||'').replace(/[^+0-9]/g,'');if(clean.replace(/\D/g,'').length<7){toast('Телефон клиента недоступен');return}location.href='tel:'+clean}
function openTelegramClient(username){const clean=String(username||'').replace(/^@/,'').replace(/[^A-Za-z0-9_]/g,'');if(!clean){toast('Личный Telegram клиента недоступен');return}const url='https://t.me/'+clean;try{if(tg?.openTelegramLink)tg.openTelegramLink(url);else window.open(url,'_blank','noopener')}catch{window.location.href=url}}
function clientDetails(id){const x=S.clients.find(x=>String(x.id)===String(id));if(!x)return;const canMessage=!!x.telegram_username;openSheet(x.name,`<div class="client-detail72"><div class="client-detail72-contact"><div><span>Телефон</span><strong>${esc(x.phone||'—')}</strong></div><div class="client-detail72-actions">${canMessage?`<button class="primary" data-message-client="${esc(id)}">Написать</button>`:`<button class="secondary" disabled>Telegram недоступен</button>`}${x.phone?`<button class="secondary" data-call="${esc(x.phone)}">Позвонить</button>`:''}</div></div><div class="client-summary"><span>${x.visits} завершённых визитов</span><strong>${money(x.revenue)}</strong></div><p class="note">${x.next_visit?'Ближайший визит: '+dateLabel(date(x.next_visit))+' · '+time(x.next_visit):'Нет предстоящих визитов'}</p><form id="note-form" data-client="${esc(id)}"><label>Ваша личная заметка<textarea name="note" maxlength="2000">${esc(x.note)}</textarea></label><div class="form-error" role="alert"></div><button class="secondary">Сохранить заметку</button></form><h3>История записей</h3>${S.bookings.filter(b=>String(b.user_id)===String(id)).map(b=>`<button class="history-line history-button72" data-visit="${b.id}"><strong>${dateLabel(date(b.starts_at))} · ${time(b.starts_at)}</strong><span>${esc(b.service_name)}</span><small>${labels[b.visit_outcome||b.status]||labels[b.status]} · ${money(b.price)}</small></button>`).join('')||'<p class="note">История пока пуста.</p>'}</div>`)}
async function reorder(from,to){const all=[...S.own.services];if(to<0||to>=all.length)return;const [x]=all.splice(from,1);all.splice(to,0,x);await post('/v2/reorder',{company_id:S.own.id,ids:all.map(s=>s.id)});await refreshOwn();await render()}
async function copyLink(){try{await navigator.clipboard.writeText(link(S.own.id));toast('Ссылка скопирована')}catch{openSheet('Ваша ссылка',`<input readonly value="${link(S.own.id)}" aria-label="Скопируйте ссылку">`)}}
async function shareLink(){const url=link(S.own.id);if(navigator.share){try{await navigator.share({title:S.own.name,text:'Запишитесь ко мне онлайн 👇\n\nВыберите услугу и удобное время:',url});return}catch(e){if(e.name==='AbortError')return}}if(tg?.openTelegramLink){tg.openTelegramLink('https://t.me/share/url?url='+encodeURIComponent(url)+'&text='+encodeURIComponent('Запишитесь ко мне онлайн 👇\n\nВыберите услугу и удобное время:'));return}await copyLink()}
