if(el.id==='timezone-picker'){timezonePicker();return}
if(el.dataset.timezone){const input=document.querySelector('[name="timezone"]'),btn=document.querySelector('#timezone-picker');if(input)input.value=el.dataset.timezone;if(btn){btn.querySelector('span').textContent=zoneLabel(el.dataset.timezone);btn.querySelector('small').textContent=el.dataset.timezone}sheet.close();return}
if(el.dataset.allReviews){await showReviews(el.dataset.allReviews);return}
