async function submit(e){e.preventDefault();const form=e.target,fd=new FormData(form),b=Object.fromEntries(fd),btn=form.querySelector('button[type="submit"]')||form.querySelector('button:not([type="button"])'),error=form.querySelector('.form-error');if(btn)btn.disabled=true;if(error)error.textContent='';try{
if(form.id==='manual-client-form'){manualNewClient={name:b.name,phone:b.phone};manualClient={name:b.name,phone:b.phone};manualServices();return}
if(form.id==='copy-days-form'){const origin=document.querySelector('#settings-form')||document.querySelector('#register-form'),source=Number(form.dataset.source),hours=readSchedule(new FormData(origin));for(const target of fd.getAll('target')){const check=origin.querySelector('[name="day'+target+'"]');check.checked=!!hours[source];origin.querySelector('[data-day-intervals="'+target+'"]').innerHTML=(hours[source]||[{start:540,end:1080}]).map(d=>intervalInputs(target,d)).join('')}sheet.close();toast('Расписание применено. Сохраните изменения.');return}
if(form.id==='register-form'){if(S.step===2)await requestMessages();saveDraft();if(S.step<2){S.step++;await render();scrollTo({top:0});return}const result=await post('/v2/register',{...S.draft,price:Number(S.draft.price),duration:Number(S.draft.duration)});S.me=await api('/me');await refreshOwn();S.page='share';await render();toast('Ваша страница готова');return}
if(form.id==='service-form'){await post('/v2/services',{...b,price:Number(b.price),duration:Number(b.duration),position:Number(b.position),active:Number(b.active),company_id:S.own.id,id:form.dataset.id||undefined,request_key:form.dataset.key,photo:S.photo});sheet.close();await refreshOwn();await render();toast('Услуга сохранена');return}
if(form.id==='handle-form'){await post('/v2/handle',{company_id:S.own.id,username:b.username});await refreshOwn();await render();toast('Ваш адрес сохранён');return}
if(form.id==='settings-form'){await post('/v2/settings',{...b,min_notice:Number(b.min_notice),horizon:Number(b.horizon),buffer:Number(b.buffer),allow_reschedule:fd.has('allow_reschedule'),notifications:Object.fromEntries(['created','cancelled','moved','reminders','client_2h','master_2h','client_events','daily_summary','summary','master_reminder'].map(k=>[k,fd.has('notify_'+k)])),company_id:S.own.id,photo:S.own.photo,cancel_hours:Number(S.own.reschedule_hours??S.own.cancel_hours),schedule:readSchedule(fd)});await refreshOwn();await render();toast('Настройки сохранены');return}
if(form.id==='block-form'){await post('/v2/blocks',{company_id:S.own.id,starts_at:b.whole_days?Math.max(Math.floor(Date.now()/1000)+1,unix(b.date,'00:00')):unix(b.date,b.start),ends_at:b.whole_days?unix(shift(b.end_date,1),'00:00'):unix(b.end_date,b.end),label:b.label});sheet.close();invalidate('work');await render({force:true});toast('Время закрыто');return}
if(form.id==='note-form'){await post('/v2/client-note',{company_id:S.own.id,client_id:form.dataset.client,note:b.note});sheet.close();await render();toast('Заметка сохранена');return}
if(form.id==='client-message-form'){throw Error('Переписка через Takt отключена. Откройте личный Telegram клиента.')}
if(form.id==='support-form'){await post('/v72/support',{message:b.message});sheet.close();toast('Обращение отправлено в поддержку');return}
if(form.id==='review-form'){await post('/v7/reviews',{booking_id:form.dataset.booking,rating:Number(b.rating),text:b.text||''});sheet.close();invalidate('my','reviews');if(isClient()){S.bookings=await api('/bookings');dataLoaded.my=Date.now()}else{await refreshOwn();S.reviews=(await api('/v7/reviews?company='+S.own.id+'&limit=100')).items;dataLoaded.reviews=Date.now()}await render();toast('Спасибо за отзыв 💙');return}
if(form.id==='booking-contact'){Object.assign(booking,b);booking.step=2;await bookingSheet();return}
}catch(err){if(error)error.textContent=translateText(err.message,S.language);else toast(err.message)}finally{if(btn)btn.disabled=false}}
root.addEventListener('submit',submit);sheet.addEventListener('submit',submit);
async function change(e){const el=e.target;try{if(el.id==='demo-role'){S.role=el.value;await init()}if(el.id==='calendar-date'){S.date=el.value;await render()}if(el.id==='booking-date'){booking.date=el.value;await bookingSheet()}if(el.dataset.photo){const file=el.files?.[0];if(!file)return;if(file.size>15*1024*1024)throw Error('Выберите фото размером до 15 МБ');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=320;canvas.height=320;const ctx=canvas.getContext('2d'),side=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,320,320);bitmap.close();const photo=canvas.toDataURL('image/jpeg',.65);if(el.dataset.photo==='draft')S.draft.photo=photo;else if(el.dataset.photo==='settings')S.own.photo=photo;else S.photo=photo;const preview=el.closest('label').querySelector('.upload-avatar');preview.outerHTML=imageTag(photo,'Фото','upload-avatar');toast('Фото добавлено')}}catch(err){toast(err.message)}}
root.addEventListener('change',change);sheet.addEventListener('change',change);
function filterClients(e){if(['client-search','manual-search','timezone-search','admin-search'].includes(e.target.id)){const q=e.target.value.toLowerCase();const scope=e.target.id==='timezone-search'?sheet:document;scope.querySelectorAll('[data-search]').forEach(x=>x.hidden=!x.dataset.search.includes(q))}}
root.addEventListener('input',filterClients);sheet.addEventListener('input',filterClients);
let dragged=null;root.addEventListener('dragstart',e=>{dragged=e.target.closest('[data-service-card]')?.dataset.serviceCard||null});root.addEventListener('dragover',e=>{if(e.target.closest('[data-service-card]'))e.preventDefault()});root.addEventListener('drop',async e=>{e.preventDefault();const target=e.target.closest('[data-service-card]')?.dataset.serviceCard;if(!target||!dragged||target===dragged)return;try{await reorder(S.own.services.findIndex(x=>x.id===dragged),S.own.services.findIndex(x=>x.id===target))}catch(err){toast(err.message)}dragged=null});

sheet.addEventListener('close',()=>slotRequest++);
async function updateFree(){if(S.page!=='dashboard'||!S.own||S.tour)return;const s=S.own.services.find(x=>x.active),target=document.querySelector('#free-count');if(!target)return;if(!s){target.textContent='—';return}try{const slots=await api('/slots?company='+S.own.id+'&service='+s.id+'&date='+day());if(document.querySelector('#free-count')===target){target.textContent=slots.length;document.querySelector('#free-label').textContent='для «'+s.name+'»'}}catch{target.textContent='—'}}
const observer=new MutationObserver(()=>{if(document.querySelector('#free-count')?.textContent==='…')updateFree()});observer.observe(root,{childList:true,subtree:true});
setInterval(async()=>{if(pollBusy||document.hidden||sheet.open||S.tour||!S.me)return;if(!['dashboard','calendar','my'].includes(S.page))return;pollBusy=true;try{const previous=JSON.stringify([S.bookings,S.blocks]);if(isClient()){S.bookings=await api('/bookings');dataLoaded.my=Date.now()}else await workData(true);if(previous!==JSON.stringify([S.bookings,S.blocks])){const y=scrollY;await render();scrollTo({top:y})}}catch{}finally{pollBusy=false}},5000);
initDisplay(tg,toast);init();
initMobile(tg);const pickers=initPickers(()=>S.language);
function rememberNavigation(){navStack.push({page:S.page,date:S.date,calendar:S.calendar,mode:S.mode,preview:S.preview,y:scrollY});if(navStack.length>30)navStack.shift()}
async function goBack(){if(pickers.close())return;if(sheet.open){const back=sheet.querySelector('#booking-back,#manual-back-services,#manual-back-clients');if(back){back.click();return}sheet.close();updateBack();return}if(S.preview){document.querySelector('#exit-preview')?.click();return}if(S.page==='register'&&S.step){saveDraft();S.step--;await render();return}const previous=navStack.pop();if(previous){S.page=previous.page;S.date=previous.date;S.calendar=previous.calendar;S.mode=previous.mode;S.preview=previous.preview;await render();requestAnimationFrame(()=>scrollTo({top:previous.y||0,behavior:'auto'}));return}S.page=isClient()?'client':S.own?(['services','settings','share','analytics','reviews','subscription','profile','help','legal'].includes(S.page)?'more':'dashboard'):'landing';await render();scrollTo({top:0})}
tg?.BackButton?.onClick(goBack);
function updateBack(){const show=pickers?.isOpen()||sheet.open||S.preview||navStack.length>0||!['dashboard','client','landing'].includes(S.page),native=!!tg?.BackButton&&typeof tg.BackButton.show==='function',custom=document.querySelector('#app-back');if(custom)custom.hidden=!show||native;try{if(native)(show?tg.BackButton.show():tg.BackButton.hide())}catch{}}
new MutationObserver(updateBack).observe(root,{childList:true,subtree:true});new MutationObserver(updateBack).observe(sheet,{attributes:true,attributeFilter:['open']});

async function loadDeliveryStatus(){try{const x=await api('/v4/delivery?company='+S.own.id),target=document.querySelector('#delivery-status');if(target){const issue=(x.blocked||0)+(x.failed||0)+(x.unknown||0)+(x.sending||0);target.textContent=issue?'Есть сообщения без подтверждённой доставки. Takt продолжит обработку автоматически.':'Уведомления работают автоматически.'}}catch{}}

async function loadClientNext(){const target=document.querySelector('#client-next'),tenant=S.tenant,service=tenant?.services[0];if(!target||!service)return;try{const x=await api('/next-slot?company='+tenant.id+'&service='+service.id+'&date='+day(-1));if(document.querySelector('#client-next')!==target)return;target.innerHTML=x.date?`Ближайшее время · ${esc(service.name)}<br><b>${dateLabel(x.date)}, ${time(x.starts_at)}</b>`:'Ближайшие даты заняты. Свяжитесь со специалистом.'}catch{}}

let messageAllowed=!!tg?.initDataUnsafe?.user?.allows_write_to_pm,messageRequest=null;
function requestMessages(force=false){if(messageAllowed&&!force)return Promise.resolve(true);if(messageRequest)return messageRequest;if(!tg?.requestWriteAccess){if(force)toast('Откройте чат с ботом и нажмите /start, чтобы получать сообщения.');return Promise.resolve(false)}messageRequest=new Promise(resolve=>{let done=false;const finish=ok=>{if(done)return;done=true;clearTimeout(timer);messageAllowed=!!ok;messageRequest=null;if(ok)post('/v5/notifications',{}).catch(()=>{});if(force)toast(ok?'Сообщения разрешены':'Разрешение можно дать позже в чате бота.');resolve(!!ok)};const timer=setTimeout(()=>finish(false),20000);try{tg.requestWriteAccess(finish)}catch{finish(false)}});return messageRequest}
function adminPage(){const a=S.admin||{},t=a.totals||{},ops=a.operations||{},bs=a.bookingStats||{},subs=a.subscriptions||{},counts=[['Специалисты',t.specialists||0],['Клиентские профили',t.clients||0],['Все записи',t.bookings||0],['Активные · 24 ч',t.active||0],['Новые кабинеты · 24 ч',t.registrations||0],['Обращения · 7 дней',ops.support7d||0]],states={sent:'Доставлено',queued:'В очереди',retry:'Ожидают повтора',blocked:'Бот заблокирован',failed:'Не доставлено',unknown:'Не подтверждено',sending:'Отправляются'},errors={DELIVERY_UNKNOWN:'Telegram не подтвердил доставку',DELIVERY_FAILED:'Сбой фоновой отправки',REQUEST_FAILED:'Не удалось обработать запрос','403':'Получатель запретил сообщения','429':'Telegram ограничил частоту','400':'Telegram отклонил сообщение'};const subRows=[['Пробный период',subs.trial||0],['Активные',subs.active||0],['Пауза',subs.expired||0],['Льготный период',subs.grace||0]];return `${heading('Контроль Takt','Закрытая панель администратора сервиса','<button class="secondary" id="refresh">Обновить</button>')}<section class="admin-v81-overview"><div class="admin-metrics">${counts.map(([label,n])=>`<article><strong>${n}</strong><span>${label}</span></article>`).join('')}</div><div class="admin-health"><div><span>Записей сегодня</span><strong>${bs.today||0}</strong></div><div><span>За 7 дней</span><strong>${bs.week||0}</strong></div><div><span>За месяц</span><strong>${bs.month||0}</strong></div><div><span>Завершённые записи</span><strong>${bs.done||0}</strong></div><div><span>Не пришли</span><strong>${bs.no_show||0}</strong></div><div><span>Отмены</span><strong>${bs.cancelled||0}</strong></div><div><span>Ждут подтверждения</span><strong>${ops.pending||0}</strong></div><div><span>Отменено · 30 дней</span><strong>${ops.cancelled30||0}</strong></div></div></section><label class="search-label admin-search-v81">${icon('user')}<input id="admin-search" type="search" placeholder="Поиск по кабинетам, обращениям и записям" aria-label="Поиск в админ-панели"></label><div class="admin-grid-v81"><section class="editor-card"><h2>Подписки</h2><p class="note">Состояние доступа специалистов. Эти данные видит только администратор.</p><div class="admin-states">${subRows.map(([label,n])=>`<div><span>${label}</span><b>${n}</b></div>`).join('')}</div></section><section class="editor-card"><h2>Telegram · 24 часа</h2><p class="note">${a.bot_configured?'Бот подключён':'Токен бота не настроен'}</p><div class="admin-states">${(a.delivery||[]).map(x=>`<div><span>${states[x.state]||'Обработано'}</span><b>${x.count}</b></div>`).join('')||'<p class="note">Сообщений пока нет.</p>'}</div></section><section class="editor-card"><h2>Языки пользователей</h2><div class="admin-states">${(a.languages||[]).map(x=>`<div><span>${({ru:'Русский',kk:'Қазақша',az:'Azərbaycan dili',uz:'O‘zbekcha'}[x.language]||'Не выбран')}</span><b>${x.count}</b></div>`).join('')||'<p class="note">Пока нет данных.</p>'}</div></section><section class="editor-card"><h2>Фоновые задачи</h2>${(a.tasks||[]).map(x=>`<p><b>${esc(x.name)}</b><br>${x.state==='error'?'Требуется проверка':x.state==='running'?'Выполняется':'Работает'}<br><small>${new Date(x.started_at*1000).toLocaleString(localeFor(S.language))}</small></p>`).join('')||'<p class="note">Ожидаем первый запуск.</p>'}</section></div><section class="editor-card admin-table-v81"><div class="section-heading"><h2>Новые кабинеты</h2><span>${(a.recentCompanies||[]).length}</span></div>${(a.recentCompanies||[]).map(x=>`<article data-search="${esc(((x.name||'')+' '+(x.category||'')+' '+(x.id||'')).toLowerCase())}"><div><strong>${esc(x.name||'Без названия')}</strong><small>${esc(x.category||'')} · ${new Date(x.created_at*1000).toLocaleString(localeFor(S.language))}</small></div><code>${esc(x.id)}</code></article>`).join('')||'<p class="note">Новых кабинетов нет.</p>'}</section><section class="editor-card admin-table-v81"><div class="section-heading"><h2>Последние обращения</h2><span>${(a.recentSupport||[]).length}</span></div>${(a.recentSupport||[]).map(x=>`<article data-search="${esc(((x.name||'')+' '+(x.message||'')+' '+(x.user_id||'')).toLowerCase())}"><div><strong>${esc(x.name||'Пользователь')}</strong><small>${new Date(x.created_at*1000).toLocaleString(localeFor(S.language))}</small><p>${esc(x.message)}</p></div><code>${esc(x.user_id)}</code></article>`).join('')||'<p class="note">Обращений нет.</p>'}</section><section class="editor-card admin-table-v81"><div class="section-heading"><h2>Последние записи</h2><span>${(a.recentBookings||[]).length}</span></div>${(a.recentBookings||[]).map(x=>`<article data-search="${esc(((x.company_name||'')+' '+(x.name||'')+' '+(x.service_name||'')+' '+(x.status||'')).toLowerCase())}"><div><strong>${esc(x.company_name)} · ${esc(x.name)}</strong><small>${esc(x.service_name)} · ${labels[x.status]||esc(x.status)} · ${new Date(x.created_at*1000).toLocaleString(localeFor(S.language))}</small></div><strong>${money(x.price)}</strong></article>`).join('')||'<p class="note">Записей пока нет.</p>'}</section><section class="editor-card"><h2>Ошибки · 24 часа</h2>${(a.errors||[]).map(e=>`<p>${errors[e.code]||esc(e.code||'Ошибка')} <b>× ${e.count}</b><br><small>${e.last_at?new Date(e.last_at*1000).toLocaleString(localeFor(S.language)):''}</small></p>`).join('')||'<p class="note">Зарегистрированных ошибок нет.</p>'}</section>${adminControls()}`}
